async function loadUsers() {
  try {
    const res = await fetch('https://api.example.com/users');
    if (!res.ok) {
      throw new Error('Request failed');
    }
    const data = await res.json();
    console.log(data);
  } catch (error) {
    console.log(error.message);
  }
}
loadUsers();
